def get_user(uid):
    if (cached := redis.get(f"user:{uid}")) is not None:
        return json.loads(cached)
    user = db.query("SELECT * FROM users WHERE id = %s", uid)
    redis.setex(f"user:{uid}", 300, json.dumps(user))
    return user

